#if UNITY_EDITOR
using System;
using System.Linq;
using HabitatShift.Core;
using UnityEditor;
using UnityEngine;
namespace HabitatShift.LevelLabR10 {
public static class R10Commands {
 static void Change(R10EditorState s,string label,Action<R10Project> action) { if(s==null||s.project==null) return; Undo.RecordObject(s,label); action(s.project); R10Storage.ResetCertification(s.project); EditorUtility.SetDirty(s); }
 static string Id(R10Project p,string prefix,Func<string,bool> exists){for(var i=1;;i++){var id=prefix+"_"+i.ToString("00");if(!exists(id))return id;}}
 static bool In(LevelDto l,Vector2Int c){return c.x>=0&&c.y>=0&&c.x<l.cols&&c.y<l.rows&&(l.playableMask==null||l.playableMask.Length==0||l.playableMask.Any(x=>x.x==c.x&&x.y==c.y));}
 public static bool LegalHabitat(LevelDto l,HabitatDto moving,Vector2Int anchor){if(moving==null||moving.shape==null||moving.shape.Length==0)return false;foreach(var q in moving.shape){var c=new Vector2Int(anchor.x+q.x,anchor.y+q.y);if(!In(l,c)||(l.obstacles??Array.Empty<IntPair>()).Any(x=>x.x==c.x&&x.y==c.y))return false;foreach(var other in l.habitats??Array.Empty<HabitatDto>())if(other!=moving&&(other.shape??Array.Empty<IntPair>()).Any(o=>o.x+other.anchor.x==c.x&&o.y+other.anchor.y==c.y))return false;}return true;}
 public static void MoveHabitat(R10EditorState s,string id,Vector2Int anchor) { var h=s.project.level.habitats.FirstOrDefault(x=>x.id==id);if(h==null||!LegalHabitat(s.project.level,h,anchor))return;Change(s,"Move Habitat",p=>h.anchor=new IntPair{x=anchor.x,y=anchor.y}); }
 public static void MoveTarget(R10EditorState s,string id,Vector2Int cell) { if(!In(s.project.level,cell))return;Change(s,"Move Sproutling",p=>{var t=p.level.targets.FirstOrDefault(x=>x.id==id);if(t!=null)t.position=new FloatPair{x=cell.x+.5f,y=cell.y+.5f};}); }
 public static void MoveElevator(R10EditorState s,string id,Vector2Int cell) { if(!In(s.project.level,cell))return;Change(s,"Move Elevator",p=>{var e=p.level.elevators.FirstOrDefault(x=>x.id==id);if(e!=null)e.entry=new FloatPair{x=cell.x+.5f,y=cell.y+.5f};}); }
 public static string AddHabitat(R10EditorState s,Vector2Int cell){if(!In(s.project.level,cell))return null;var id=Id(s.project,"H",v=>(s.project.level.habitats??Array.Empty<HabitatDto>()).Any(x=>x.id==v));var h=new HabitatDto{id=id,color="green",need=1,movementConstraint="FREE",anchor=new IntPair{x=cell.x,y=cell.y},shape=new[]{new IntPair{x=0,y=0}}};if(!LegalHabitat(s.project.level,h,cell))return null;Change(s,"Add Habitat",p=>p.level.habitats=(p.level.habitats??Array.Empty<HabitatDto>()).Concat(new[]{h}).ToArray());return id;}
 public static string AddTarget(R10EditorState s,Vector2Int cell){if(!In(s.project.level,cell))return null;var id=Id(s.project,"S",v=>(s.project.level.targets??Array.Empty<TargetDto>()).Any(x=>x.id==v));Change(s,"Add Sproutling",p=>p.level.targets=(p.level.targets??Array.Empty<TargetDto>()).Concat(new[]{new TargetDto{id=id,color="green",position=new FloatPair{x=cell.x+.5f,y=cell.y+.5f}}}).ToArray());return id;}
 public static string AddElevator(R10EditorState s,Vector2Int cell){if(!In(s.project.level,cell))return null;var id=Id(s.project,"E",v=>(s.project.level.elevators??Array.Empty<ElevatorDto>()).Any(x=>x.id==v));Change(s,"Add Elevator",p=>p.level.elevators=(p.level.elevators??Array.Empty<ElevatorDto>()).Concat(new[]{new ElevatorDto{id=id,direction="UP",entry=new FloatPair{x=cell.x+.5f,y=cell.y+.5f},queue=Array.Empty<QueueItemDto>()}}).ToArray());return id;}
 public static void Delete(R10EditorState s,R10Selection x){if(!x.Has)return;Change(s,"Delete "+x.kind,p=>{if(x.kind=="Habitat")p.level.habitats=p.level.habitats.Where(v=>v.id!=x.id).ToArray();else if(x.kind=="Sproutling")p.level.targets=p.level.targets.Where(v=>v.id!=x.id).ToArray();else if(x.kind=="Elevator")p.level.elevators=p.level.elevators.Where(v=>v.id!=x.id).ToArray();});x.Clear();}
 public static string DuplicateHabitat(R10EditorState s,string id,Vector2Int anchor){var original=s.project.level.habitats.FirstOrDefault(x=>x.id==id);if(original==null)return null;var copy=R10Storage.CloneHabitat(original);copy.id=Id(s.project,original.id+"_COPY",v=>s.project.level.habitats.Any(x=>x.id==v));copy.anchor=new IntPair{x=anchor.x,y=anchor.y};if(!LegalHabitat(s.project.level,copy,anchor))return null;Change(s,"Duplicate Habitat",p=>p.level.habitats=p.level.habitats.Concat(new[]{copy}).ToArray());return copy.id;}
 public static void SetStages(R10EditorState s,string id,HabitatStageDto[] stages) { Change(s,"Edit Habitat Stages",p=>{var h=p.level.habitats.First(x=>x.id==id);h.stages=stages;h.color=null;h.need=0;}); }
 public static void EditQueue(R10EditorState s,string id,QueueItemDto[] q) { Change(s,"Edit Elevator Queue",p=>p.level.elevators.First(x=>x.id==id).queue=q); }
 public static void ToggleCell(R10EditorState s,Vector2Int cell,bool obstacle) { Change(s,obstacle?"Toggle Obstacle":"Toggle Playable Cell",p=> { var a=obstacle?p.level.obstacles:p.level.playableMask; var exists=(a??Array.Empty<IntPair>()).Any(v=>v.x==cell.x&&v.y==cell.y); var result=(a??Array.Empty<IntPair>()).Where(v=>v.x!=cell.x||v.y!=cell.y).ToList(); if(!exists)result.Add(new IntPair{x=cell.x,y=cell.y}); if(obstacle)p.level.obstacles=result.ToArray();else p.level.playableMask=result.ToArray(); }); }
}}
#endif